// tabularChatUsage displays the usage of the tabular-chat command and its
// subcommands.
func tabularChatUsage() {
	fmt.Fprintln(os.Stderr, "Service is the tabular_chat service interface.")
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] tabular-chat COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, "    list: List implements list.")
	fmt.Fprintln(os.Stderr, "    delete: Delete implements delete.")
	fmt.Fprintln(os.Stderr, "    messages: Messages implements messages.")
	fmt.Fprintln(os.Stderr, "    stream: Stream implements stream.")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s tabular-chat COMMAND --help\n", os.Args[0])
}
